import sys


def run(data):
    """执行一段栈式指令程序。

    data[0] 为指令条数 k，随后 k 行是指令。返回输出字符串
    （以换行结尾，或在无输出时为空串），出错时返回 None。
    """
    first = data[0].strip() if data else ''
    # 空输入/空首行视为错误（与运行期错误一致返回 None）
    if not first:
        return None
    try:
        k = int(first)
    except ValueError:
        return None
    if k < 0:
        return None

    prog = []
    for i in range(1, k + 1):
        if i >= len(data):
            return None
        prog.append(data[i].strip())

    pc = 0
    steps = 0
    stack = []
    out = []

    while True:
        steps += 1
        if steps > 10000:
            return None
        if pc < 0 or pc >= len(prog):
            return None
        parts = prog[pc].split()
        if not parts:
            return None
        op = parts[0]
        pc += 1

        if op == 'PUSH':
            stack.append(int(parts[1]))
        elif op == 'POP':
            if not stack:
                return None
            stack.pop()
        elif op in ('ADD', 'SUB', 'MUL'):
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            if op == 'ADD':
                stack.append(b + a)
            elif op == 'SUB':
                stack.append(b - a)
            else:
                stack.append(b * a)
        elif op == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'PRINT':
            if not stack:
                return None
            out.append(str(stack.pop()))
        elif op == 'JNZ':
            if not stack:
                return None
            v = stack.pop()
            if v != 0:
                a = int(parts[1])
                if a < 0 or a >= len(prog):
                    return None
                pc = a
        elif op == 'HALT':
            if out:
                return '\n'.join(out) + '\n'
            return ''
        else:
            return None


def main():
    data = sys.stdin.read().split('\n')
    res = run(data)
    if res is None:
        print("ERR")
    else:
        sys.stdout.write(res)


if __name__ == '__main__':
    main()
